query:
SELECT 'projects' AS section, COUNT(*) AS count_value FROM projects WHERE enterpriseName = '海豚知道';
SELECT 'questions' AS section, COUNT(*) AS count_value FROM questions q JOIN projects p ON q.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'ai_responses' AS section, COUNT(*) AS count_value FROM ai_responses a JOIN projects p ON a.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'analysis_results' AS section, COUNT(*) AS count_value FROM analysis_results ar JOIN projects p ON ar.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'geo_scores' AS section, COUNT(*) AS count_value FROM geo_scores gs JOIN projects p ON gs.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'optimization_tasks' AS section, COUNT(*) AS count_value FROM optimization_tasks ot JOIN projects p ON ot.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'content_templates' AS section, COUNT(*) AS count_value FROM content_templates ct JOIN projects p ON ct.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'reports' AS section, COUNT(*) AS count_value FROM reports r JOIN projects p ON r.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'geo_articles_total' AS section, COUNT(*) AS count_value FROM geo_articles ga JOIN projects p ON ga.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'geo_articles_published' AS section, COUNT(*) AS count_value FROM geo_articles ga JOIN projects p ON ga.projectId = p.id WHERE p.enterpriseName = '海豚知道' AND ga.status = '已发布';
SELECT 'geo_publish_records' AS section, COUNT(*) AS count_value FROM geo_publish_records gpr JOIN projects p ON gpr.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'enterprise_profiles' AS section, COUNT(*) AS count_value FROM enterprise_geo_profiles ep JOIN projects p ON ep.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'asset_sources' AS section, COUNT(*) AS count_value FROM geo_asset_sources s JOIN projects p ON s.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'customer_cases' AS section, COUNT(*) AS count_value FROM customer_cases cc JOIN projects p ON cc.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'competitor_profiles' AS section, COUNT(*) AS count_value FROM competitor_profiles cp JOIN projects p ON cp.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'compliance_rules' AS section, COUNT(*) AS count_value FROM compliance_rules cr JOIN projects p ON cr.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'content_style_profiles' AS section, COUNT(*) AS count_value FROM content_style_profiles csp JOIN projects p ON csp.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT 'publish_strategies' AS section, COUNT(*) AS count_value FROM publish_strategies ps JOIN projects p ON ps.projectId = p.id WHERE p.enterpriseName = '海豚知道';
SELECT ga.id, ga.title, ga.articleType, ga.status, ga.publicPath, LENGTH(COALESCE(ga.generationBasis,'')) AS basis_len, LENGTH(COALESCE(ga.factTraceability,'')) AS facts_len, LENGTH(COALESCE(ga.consistencyCheck,'')) AS consistency_len, LENGTH(COALESCE(ga.citableSnippets,'')) AS snippets_len FROM geo_articles ga JOIN projects p ON ga.projectId = p.id WHERE p.enterpriseName = '海豚知道' ORDER BY ga.id LIMIT 10;
SELECT gpr.articleId, gpr.publishChannel, gpr.publishStatus, gpr.publishUrl, gpr.qualityScore, gpr.needRetest FROM geo_publish_records gpr JOIN projects p ON gpr.projectId = p.id WHERE p.enterpriseName = '海豚知道' ORDER BY gpr.id LIMIT 5;
SELECT r.id, r.totalScore, LEFT(r.oneSentenceConclusion, 120) AS conclusion_excerpt, LOCATE('样本量有限', r.markdownContent) AS has_limited_sample_risk FROM reports r JOIN projects p ON r.projectId = p.id WHERE p.enterpriseName = '海豚知道' ORDER BY r.id DESC LIMIT 3;

